-- The two checklists published on 2026-10-26: Facing the Whole Picture of
-- What You Owe (Debt) and When a Family Member Stops Speaking to You
-- (Estrangement).
-- Generated by `python3 tools/checklists_sql.py --since 2026-10-26`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('facing-the-whole-picture-of-what-you-owe', 'Facing the Whole Picture of What You Owe', 'For the point where you stop guessing and put every debt on one page. It gets the rates in order, finds free advice rather than paid, sets one monthly amount you can actually keep, and separates owing money from what kind of person you are.', 'Debt', '["Write every debt on one page — the total is usually less frightening than not knowing.", "Put the interest rate beside each one — the order to pay them in falls out of that.", "Call the worst one first and ask for terms — most lenders have a plan they do not advertise.", "Find the free advice line in your state — paid debt help is rarely better than free help.", "Set one amount that leaves the house monthly — a plan you keep beats a plan that is faster.", "Separate the debt from your character — owing money is arithmetic, not a verdict on you.", "Tell one person the real number — the secret costs more than the interest does.", "Put the date of the next review in — three months is long enough to see movement.", "Stop checking the balance daily — looking is not paying and it eats the evening."]'::jsonb, 'as needed', array['Money', 'Shame']::text[], 1, '2026-10-26T16:00:00+00:00'::timestamptz),
  ('when-a-family-member-stops-speaking-to-you', 'When a Family Member Stops Speaking to You', 'For a parent, sibling or child who has stopped speaking to you. It keeps the door unlocked without leaving you waiting at it, gets the unsent letter written, settles what to tell people who ask, and expects the anniversaries to hurt.', 'Estrangement', '["Send one short message, then stop sending — a door left open is not the same as knocking.", "Write the long letter and keep it — it does its work whether or not it is sent.", "Decide what you would apologize for — your share, named plainly, without the rest of the case.", "Ask one relative to carry nothing — messengers make a second argument out of the first.", "Let the anniversaries be hard — birthdays and holidays will hurt and that is not failure.", "Answer the question in public simply — “we are not in touch right now” is a whole answer.", "Build the family you do have — the people who answer are not a consolation prize.", "Leave the door unlocked, not open — being reachable costs you less than waiting does."]'::jsonb, 'as needed', array['Family', 'Self-Compassion']::text[], 1, '2026-10-26T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
